{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const matching = issues.filter(i => i.status === "unresolved" && i.count >= 50);
  const created = [];
  for (const issue of matching) {
    created.push(await sdk.linear.createIssue({
      title: `[Sentry] ${issue.shortId}`,
      description: issue.culprit,
    }));
  }
  return { count: created.length, created };
}"}

